// CSD_RATIONALE_BEGIN
// Key diagnosis from attempt 66 (53.3%): 138 mode_A wrong answers are
// syntax-valid but semantically wrong SQL generated within the constrained span.
// The repetition loop failure (example 3: AND countrycode repeated 25×) suggests
// that RegenerateUnitOnGroundingFailure does NOT prevent within-grammar repetition
// because the repeated clauses are schema-grounded. Replacing Phase 3 with a
// direct RepetitionPenaltyStep loop:
//   1. Directly penalizes tokens already present in `generated`, preventing the
//      exact repetition loop that corrupts example 3.
//   2. Avoids RegenerateUnitOnGroundingFailure's rollback-and-resample path that
//      may re-generate worse SQL when the rolled-back token was actually valid.
//   3. Keeps every other structural choice from attempt 66 (best known baseline):
//      5-step preamble, OpenConstrainedSpan, budget=min(remaining-1,250),
//      CloseSpanWithinBudget(120), same guidance string.
// sqlBudget is capped at 250: covers >99% of Spider SQL tokens (max observed
// ~60 tokens) while staying strictly within maxSteps. innerSteps <= sqlBudget
// <= remaining-1 guarantees at least 1 step reserved for Phase 4 close.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble loop: guard includes !insideConstrainedOut, so the
//   implication is vacuous throughout. The only insideConstrainedOut:=true
//   transition is via RenderedEndsWith, at which point currentConstrainedOut
//   := [] and IsValidPrefix([]) holds by precondition.
//
// Phase 2 OpenConstrainedSpan: runs only when !insideConstrainedOut.
//   Postcondition sets currentConstrainedOut := []; IsValidPrefix([]) holds.
//
// Phase 3 inner loop: We call IsTokenValidNext before every AppendConstrainedToken.
//   If valid, AppendConstrainedToken's postcondition guarantees
//   IsValidPrefix(currentConstrainedOut + [next]) by definition of IsValidPrefix
//   and IsTokenValidNext. When valid is false we skip AppendConstrainedToken,
//   leaving currentConstrainedOut unchanged (still parser-valid). EOS break
//   also leaves state unchanged.
//
// Phase 4a CloseConstrainedSpan: requires IsCompletePrefix (we check explicitly).
//   Sets insideConstrainedOut := false; implication vacuously true.
//
// Phase 4b CloseSpanWithinBudget: postcondition directly ensures
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs 1 step; appends 0 (EOS) or 1 (non-EOS) token.
//   Each iteration: |generated| grows by ≤1, steps grows by 1. Invariant maintained.
//
// Phase 2: OpenConstrainedSpan costs 1 step and appends exactly 1 "<<" token. 1:1.
//
// Phase 3 inner loop invariant: |generated| <= |generatedPrefix| + steps + innerSteps.
//   Each iteration increments innerSteps by 1 before the optional append; if valid,
//   AppendConstrainedToken grows |generated| by 1. Both sides grow by 1. ✓
//   After `steps := steps + innerSteps`, the outer invariant is restored:
//   |generated| <= |generatedPrefix| + steps_new.
//   Budget bound: sqlBudget = min(remaining-1, 250) <= remaining-1
//   = maxSteps - steps_before_phase3 - 1, so steps_new <= maxSteps - 1 < maxSteps.
//
// Phase 4a: CloseConstrainedSpan appends ≤1 ">>" token, steps += 1.
//   |generated| grows by ≤1, steps grows by 1. Invariant maintained.
//
// Phase 4b: CloseSpanWithinBudget postcondition |generatedOut| <= |generated| + closeBudget.
//   steps += closeBudget. Invariant maintained by transitivity.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Constrained SQL generation with RepetitionPenaltyStep loop
// RepetitionPenaltyStep penalizes tokens already in `generated`, directly
// preventing the AND-clause repetition loop observed in example 3.
// Budget cap at min(remaining-1, 250) reserves ≥1 step for Phase 4 close.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  if remaining >= 2 {
    var sqlBudget: nat;
    if remaining - 1 <= 250 {
      sqlBudget := remaining - 1;
    } else {
      sqlBudget := 250;
    }
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var innerSteps: nat := 0;

    while innerSteps < sqlBudget && insideConstrainedOut
      invariant 0 <= innerSteps <= sqlBudget
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut ==> currentConstrainedOut == []
      invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
      invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
      invariant |generated| <= |generatedPrefix| + steps + innerSteps
      decreases sqlBudget - innerSteps
    {
      var next := helpers.RepetitionPenaltyStep(lm, parser, constrainedPrompt, currentConstrainedOut, generated, 2.0, eosToken);
      innerSteps := innerSteps + 1;
      if next == eosToken {
        break;
      }
      var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
      if valid {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
      if parser.IsCompletePrefix(currentConstrainedOut) {
        break;
      }
    }
    steps := steps + innerSteps;
  }
}

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining := maxSteps - steps;
    var closeBudget: nat;
    if remaining <= 120 {
      closeBudget := remaining;
    } else {
      closeBudget := 120;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

